function createMoney(amount, currency = 'USD') {
  return {
    amount,
    currency,
    [Symbol.toPrimitive](hint) {
      if (hint === 'string') {
        return `${this.currency} ${this.amount}`;
      }
      return this.amount;
    }
  };
}
